const result = {};

for (const item of items) {

  if (item.json.sales_summary) {
    result.sales_summary = item.json.sales_summary;
    result.opportunity_level = item.json.opportunity_level;
    result.buying_stage = item.json.buying_stage;
    result.recommended_solution = item.json.recommended_solution;
  }

  if (item.json.hr_summary) {
    result.hr_summary = item.json.hr_summary;
    result.recommended_hr_solution = item.json.recommended_hr_solution;
  }

  if (item.json.support_summary) {
    result.support_summary = item.json.support_summary;
    result.recommended_support_solution = item.json.recommended_support_solution;
  }

  if (item.json.finance_summary) {
    result.finance_summary = item.json.finance_summary;
    result.project_size = item.json.project_size;
    result.expected_roi = item.json.expected_roi;
  }

}

return [
  {
    json: result
  }
];

